function selectItem(id,e,ids){selecting=true;if(e.shiftKey&&anchor!=null){const a=ids.indexOf(anchor),b=ids.indexOf(id),remove=selection.has(id);const range=a>=0&&b>=0?ids.slice(Math.min(a,b),Math.max(a,b)+1):[id];range.forEach(x=>remove?selection.delete(x):selection.add(x));if(remove)selection.add(id)}else if(selection.has(id)){selection.delete(id)}else{selection.add(id)}anchor=id;renderSidebar();renderToolbar();if(state.active==='albums')renderCards($('#grid-search')?.value||'');else renderGallery()}
const removalUndo=[];
