function renameInline(el,obj,key,old){if(!el||el.querySelector('input'))return;const input=document.createElement('input');input.className='inline-rename';input.value=old;el.replaceChildren(input);let done=false;const finish=cancel=>{if(done)return;done=true;const value=input.value.trim();if(!cancel&&value)obj[key]=value;else if(!cancel)notify('Enter a nonempty name.');render();persist()};input.onclick=e=>e.stopPropagation();input.ondblclick=e=>e.stopPropagation();input.onkeydown=e=>{e.stopPropagation();if(e.key==='Enter')finish(false);if(e.key==='Escape')finish(true)};input.onblur=()=>finish(false);input.focus();input.select()}
function coverEditor(a){let cover=[...a.cover];const choices=a.items?posts.filter(p=>a.items.includes(p.id)):filtered({...makeView(a.q),filters:a.filters});const draw=()=>{showDialog(`<h2>Edit cover</h2><img class="cover-main" id="cover-main" draggable="false" src="${posts.find(p=>p.id===cover[0])?.src||'assets/scene-1.svg'}" alt="Primary cover"><div class="cover-support">${cover.slice(1).map((id,i)=>`<img src="${posts.find(p=>p.id===id)?.src}" data-cover-slot="${i+1}" draggable="true" alt="Supporting image ${i+1}">`).join('')}</div><input type="text" id="cover-search" placeholder="Find album images by tag…" aria-label="Find cover images by tag"><div class="cover-candidates"></div><div class="dialog-actions"><button type="button" id="auto-cover">Auto-select</button><button value="cancel">Cancel</button><button type="button" class="primary" id="cover-save">Save</button></div>`);const candidates=q=>{$('.cover-candidates').innerHTML=choices.filter(p=>p.tags.some(t=>t.includes(q))).map(p=>`<img src="${p.src}" data-candidate="${p.id}" draggable="true" alt="Choose sample ${p.id}" tabindex="0">`).join('');$$('[data-candidate]').forEach(img=>{img.ondragstart=e=>{coverDrag={id:+img.dataset.candidate};e.dataTransfer.effectAllowed='copyMove';e.dataTransfer.setData('text/plain',JSON.stringify(coverDrag));e.stopPropagation()};img.ondragend=()=>{coverDrag=null;$('#cover-main')?.classList.remove('drag-over')};img.onclick=()=>{const id=+img.dataset.candidate;if(!cover.includes(id)){if(cover.length<4)cover.push(id);else cover[3]=id;$('#dialog').close();draw()}}})};candidates('');$('#cover-search').oninput=e=>candidates(e.target.value);const receive=(e,to)=>{e.preventDefault();e.stopPropagation();let drag=coverDrag;if(!drag){try{drag=JSON.parse(e.dataTransfer.getData('text/plain'))}catch{}}if(!drag)return;const from=Number.isInteger(drag.slot)?drag.slot:cover.indexOf(drag.id);if(from>=0){[cover[to],cover[from]]=[cover[from],cover[to]]}else if(choices.some(p=>p.id===drag.id)){cover[to]=drag.id}else return;coverDrag=null;$('#dialog').close();draw()};$$('[data-cover-slot]').forEach(img=>{img.ondragstart=e=>{coverDrag={slot:+img.dataset.coverSlot,id:cover[+img.dataset.coverSlot]};e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',JSON.stringify(coverDrag));e.stopPropagation()};img.ondragend=()=>{coverDrag=null;$('#cover-main')?.classList.remove('drag-over')};img.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move'};img.ondrop=e=>receive(e,+img.dataset.coverSlot)});$('#cover-main').ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move';$('#cover-main').classList.add('drag-over')};$('#cover-main').ondragleave=()=>$('#cover-main').classList.remove('drag-over');$('#cover-main').ondrop=e=>receive(e,0);$('#auto-cover').onclick=()=>{cover=choices.slice(0,4).map(p=>p.id);$('#dialog').close();draw();notify('Sample selection only; color analysis is not implemented.')};$('#cover-save').onclick=()=>{a.cover=cover;$('#dialog').close();render();persist()}};draw()}
function customize(v){showDialog(`<h2>Customize view</h2><label>Icon <select id="custom-icon">${['search','artist','book-image','heart','star'].map(x=>`<option ${v.customIcon===x?'selected':''}>${x}</option>`).join('')}</select></label><p><label>Icon color <input type="color" id="custom-color" value="${v.color||'#8fb5e5'}"></label></p><div class="dialog-actions"><button type="button" id="reset-custom">Reset</button><button value="cancel">Cancel</button><button type="button" class="primary" id="save-custom">Save</button></div>`);$('#reset-custom').onclick=()=>{v.customIcon=null;v.color=null;v.title=null;$('#dialog').close();renderSidebar();persist()};$('#save-custom').onclick=()=>{v.customIcon=$('#custom-icon').value;v.color=$('#custom-color').value;$('#dialog').close();renderSidebar();persist()}}
function openPopup(anchor,html,setup=()=>{},extra=''){const isButton=anchor.tagName==='BUTTON';if(isButton&&!$('#popup').hidden&&popupAnchor===anchor){closePopup();return}$('#gallery-options-float')?.classList.remove('popover-open');const rect=anchor.getBoundingClientRect();$('#context-menu').hidden=true;$('#popup').className='popup '+extra;$('#popup').innerHTML=html;$('#popup').hidden=false;popupAnchor=anchor;if(anchor.id==='gallery-options-float')anchor.classList.add('popover-open');const width=$('#popup').offsetWidth,height=$('#popup').offsetHeight;$('#popup').style.left=Math.max(10,Math.min(rect.left,innerWidth-width-12))+'px';$('#popup').style.top=(rect.bottom+height+12>innerHeight?Math.max(10,rect.top-height-8):rect.bottom+8)+'px';setup()}
function context(e,actions){closePopup();const menu=$('#context-menu');menu.innerHTML=actions.map(([ic,label],i)=>`${ic==='trash'?'<hr>':''}<button class="menu-item ${ic==='trash'?'danger':''}" role="menuitem" data-action="${i}">${icon(ic)}${label}</button>`).join('');menu.hidden=false;const gap=4,padding=12,width=menu.offsetWidth,height=menu.offsetHeight;const left=e.clientX+gap+width>innerWidth-padding?e.clientX-width-gap:e.clientX+gap;const top=e.clientY+gap+height>innerHeight-padding?e.clientY-height-gap:e.clientY+gap;menu.style.left=Math.max(padding,Math.min(left,innerWidth-width-padding))+'px';menu.style.top=Math.max(padding,Math.min(top,innerHeight-height-padding))+'px';popupAnchor=e.currentTarget;$$('[data-action]').forEach(b=>b.onclick=()=>{const fn=actions[+b.dataset.action][2];closePopup();fn()})}
function closePopup(focus=false){$('#gallery-options-float')?.classList.remove('popover-open');$('#popup').hidden=true;$('#context-menu').hidden=true;suggestIndex=-1;suggestions=[];if(focus&&popupAnchor?.isConnected)popupAnchor.focus()}
function imageMenu(e,id){context(e,[['book-image','Add to album',()=>albumPicker($('#toolbar'),[id])],['heart',state.favorites.includes(id)?'Unfavorite':'Favorite',()=>setFavorite(id,!state.favorites.includes(id))],['download','Download',()=>download(id)],['external','Open booru page',()=>openBooru(id)],...(current()?.scope==='album'?[['trash','Remove from album',()=>{rememberRemoval('album',album().id,[id]);album().items=album().items.filter(x=>x!==id);if(isViewer())advanceRemoved(id);else renderGallery();persist()}]]:[])])}
function openBooru(){notify('Sample artwork has no Gelbooru post. Real posts would open in a new tab.')}
async function download(id){const post=posts.find(p=>p.id===id);if(!post)return;try{const response=await fetch(post.src);if(!response.ok)throw new Error('Download failed');const blob=await response.blob();saveDownloadBlob(blob,'panbooru-sample-'+id+'.svg')}catch(error){if(location.protocol==='file:'){try{const original=await readLocalSample(post.src);saveDownloadBlob(new Blob([original],{type:'image/svg+xml'}),'panbooru-sample-'+id+'.svg');return}catch{}}notify('Download failed. Please try again.')}}
function saveDownloadBlob(blob,filename){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.style.display='none';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function readLocalSample(src){return sampleDownloads[src]?Promise.resolve(sampleDownloads[src]):Promise.reject(new Error('Sample unavailable'))}

function isViewer(){return current()?.mode==='viewer'}
function clearViewerHighlights(){viewerSessionId=null;for(const v of [...state.views,...Object.values(state.destViews)])delete v.createdByViewerSession}
function openViewer(id){viewerSessionId=crypto.randomUUID();checkpoint();const v=current();v.mode='viewer';v.postId=id;viewerList=filtered(v).map(p=>p.id);$('#viewer').hidden=false;document.body.classList.add('viewing');document.body.classList.remove('left-open');renderMedia();history.pushState({id:state.active,post:id},'');persist()}
function leaveViewer(){clearViewerHighlights();swipe=null;const v=current();if(v)v.mode='gallery';$('#viewer').hidden=true;document.body.classList.remove('viewing','left-open');closePopup();render();persist()}
function renderViewerBar(){const v=current();$('#viewer-bar').innerHTML=[['book-image','Album selector · S','album'],['heart','Favorite · W','favorite'],['download','Download original','download'],['external','Open Gelbooru page','external'],['full','Fullscreen · F','full'],['panel','Details and tags · I','panel']].map(([ic,title,act])=>`<button data-viewer-action="${act}" class="${act==='favorite'&&state.favorites.includes(v.postId)?'hearted':''}" title="${title}">${icon(ic)}</button>`).join('');$$('[data-viewer-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.viewerAction;if(action==='album')albumPicker(b,[v.postId]);if(action==='favorite')setFavorite(v.postId,!state.favorites.includes(v.postId));if(action==='download')download(v.postId);if(action==='external')openBooru(v.postId);if(action==='full')toggleFullscreen();if(action==='panel')togglePanel()})}
const backdropCache=new Map();
function updateViewerBackdrop(post){const apply=url=>{if(current()?.postId===post.id)$('#viewer-backdrop').style.backgroundImage=`url("${url}")`};if(backdropCache.has(post.src))return apply(backdropCache.get(post.src));const image=new Image(),source=sampleDownloads[post.src],url=source?URL.createObjectURL(new Blob([source],{type:'image/svg+xml'})):post.src;image.onload=()=>{try{const canvas=document.createElement('canvas');const ratio=96/Math.max(post.w,post.h);canvas.width=Math.max(1,Math.round(post.w*ratio));canvas.height=Math.max(1,Math.round(post.h*ratio));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.6);backdropCache.set(post.src,data);apply(data)}catch{apply(post.src)}finally{if(source)URL.revokeObjectURL(url)}};image.src=url;}
function renderMedia(){if(!viewerSessionId)viewerSessionId=crypto.randomUUID();if($('#album-find'))closePopup();const v=current(),p=posts.find(p=>p.id===v.postId);if(!p)return leaveViewer();$('#full-image').src=p.src;updateViewerBackdrop(p);$('#full-image').alt='Sample illustrated landscape '+p.id;$('#right-panel').hidden=!v.panel;$('#viewer').classList.toggle('panel-open',v.panel);$('#viewer').style.setProperty('--view-right',v.panel?v.panelWidth+'px':'0px');document.documentElement.style.setProperty('--right',v.panelWidth+'px');const groups=['artist','character','copyright','metadata','general','deprecated'];$('#right-scroll').innerHTML=`<div class="details"><div class="details-grid"><div><span>Resolution</span><strong>${p.w} × ${p.h}</strong></div><div><span>File size</span><strong>Sample SVG</strong></div><div><span>Rating</span><strong>${p.rating}</strong></div><div><span>Score</span><strong>${p.score}</strong></div><div><span>Original post</span><a href="#" id="details-source">Gelbooru ↗</a></div></div></div><div class="tags">${groups.map(g=>{const ts=p.tags.filter(t=>category(t)===g).sort();return ts.length?`<section class="tag-group"><h3>${g[0].toUpperCase()+g.slice(1)}</h3>${ts.map(t=>`<button class="tag-row" data-tag="${t}"><span class="${g}">${t.replaceAll('_',' ')}</span><small>${(t.length*731).toLocaleString()}</small></button>`).join('')}</section>`:''}).join('')}</div>`;$('#right-scroll').scrollTop=0;$('#details-source').onclick=e=>{e.preventDefault();openBooru(p.id)};$$('[data-tag]').forEach(b=>{b.onclick=e=>tagAction(b.dataset.tag,e);b.onauxclick=e=>{if(e.button===1){e.preventDefault();tagAction(b.dataset.tag,e)}}});const at=viewerList.indexOf(p.id);for(const id of viewerList.slice(Math.max(0,at-state.preload),at+state.preload+1)){const source=posts.find(x=>x.id===id)?.src;if(source){const warm=new Image();warm.src=source;warm.decode?.().catch(()=>{})}}renderViewerBar();renderSidebar();$('#previous').disabled=viewerList.indexOf(p.id)<=0;$('#next').disabled=viewerList.indexOf(p.id)>=viewerList.length-1;zoom=1;pan={x:0,y:0};requestAnimationFrame(()=>{fitBase();transformImage()});revealControls()}
function fitBase(){const p=posts.find(p=>p.id===current()?.postId);if(!p)return;const rect=$('#media-area').getBoundingClientRect();const fit=Math.min(rect.width/p.w,rect.height/p.h);base=p.w>=state.minW||p.h>=state.minH?fit:Math.min(1,fit);$('#full-image').style.width=p.w*base+'px';$('#full-image').style.height=p.h*base+'px'}
function transformImage(){const p=posts.find(p=>p.id===current()?.postId);if(!p)return;const rect=$('#media-area').getBoundingClientRect(),maxX=Math.max(0,(p.w*base*zoom-rect.width)/2),maxY=Math.max(0,(p.h*base*zoom-rect.height)/2);pan.x=Math.max(-maxX,Math.min(maxX,pan.x));pan.y=Math.max(-maxY,Math.min(maxY,pan.y));$('#full-image').style.transform=`translate(${pan.x}px,${pan.y}px) scale(${zoom})`;$('#full-image').classList.toggle('zoomed',zoom>1.001);$('#viewer').classList.toggle('image-over-info',zoom>1.001)}
function setZoom(next,x=innerWidth/2,y=innerHeight/2){const rect=$('#media-area').getBoundingClientRect(),factor=Math.max(1,Math.min(12,next))/zoom;pan.x=(pan.x-(x-rect.left-rect.width/2))*factor+(x-rect.left-rect.width/2);pan.y=(pan.y-(y-rect.top-rect.height/2))*factor+(y-rect.top-rect.height/2);zoom=Math.max(1,Math.min(12,next));transformImage();$('#zoom-readout').textContent=Math.round(base*zoom*100)+'%';$('#zoom-readout').classList.add('visible');setTimeout(()=>$('#zoom-readout').classList.remove('visible'),900)}
function togglePanel(){const v=current(),old=base*zoom,wasZoomed=zoom>1.001;v.panel=!v.panel;$('#right-panel').hidden=!v.panel;$('#viewer').classList.toggle('panel-open',v.panel);$('#viewer').style.setProperty('--view-right',v.panel?v.panelWidth+'px':'0px');setTimeout(()=>{fitBase();if(wasZoomed)zoom=Math.max(1,old/base);transformImage()},220);persist()}
function step(dir,keyboard=false){const v=current();const i=viewerList.indexOf(v.postId),id=viewerList[i+dir];if(!id)return;closePopup();v.postId=id;renderMedia();if(keyboard)$('#viewer').classList.add('hide-controls');persist()}

function animateRemoval(image,rect,reverse=false){
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const preview=image.cloneNode();preview.removeAttribute('id');preview.className='removal-preview';Object.assign(preview.style,{position:'fixed',left:rect.left+'px',top:rect.top+'px',width:rect.width+'px',height:rect.height+'px',objectFit:'contain',pointerEvents:'none',zIndex:'1',transformOrigin:'50% 65%',willChange:'transform,opacity'});(isViewer()?$('#viewer'):document.body).append(preview);
 const frames=reverse?[{transform:'translateY(24px) scale(.94)',opacity:0},{offset:.35,transform:'translateY(0) scale(1)',opacity:.85},{offset:.7,transform:'translateY(0) scale(1)',opacity:.85},{transform:'translateY(-6px) scale(1)',opacity:0}]:[{transform:'translateY(0) rotate(0deg) scale(1)',opacity:1},{transform:'translateY(90px) rotate(4deg) scale(.94)',opacity:0}];
 preview.animate(frames,{duration:reverse?650:480,easing:'cubic-bezier(.2,.65,.3,1)'}).finished.finally(()=>preview.remove())
}
function advanceRemoved(id){if(current()?.postId!==id)return;const old=viewerList.indexOf(id),image=$('#full-image'),rect=image.getBoundingClientRect(),v=current(),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduce)animateRemoval(image,rect);viewerList=filtered().map(p=>p.id);if(!viewerList.length)return leaveViewer();const previous=old>=viewerList.length;v.postId=viewerList[Math.min(old,viewerList.length-1)];renderMedia();if(!reduce)requestAnimationFrame(()=>{if(current()!==v||!isViewer())return;const transform=image.style.transform;image.animate([{transform:'translateX('+(previous?'-':'')+'110vw) '+transform,opacity:.6},{transform,opacity:1}],{duration:440,easing:'cubic-bezier(.2,.75,.25,1)'})})}
function tagAction(tag,e){if(e.ctrlKey||e.metaKey||e.button===1)return newView(tag,true,'remote',null,null,e.currentTarget);const v=current();v.draft=e.shiftKey?[v.q,tag].filter(Boolean).join(' '):tag;if(!e.shiftKey)v.draftFilters=freshFilters();leaveViewer();submit();v.draft+=' ';$('#query').value=v.draft;$('#query').focus();$('#query').setSelectionRange(v.draft.length,v.draft.length)}
function revealControls(){if(!isViewer())return;$('#viewer').classList.remove('hide-controls');clearTimeout(hideTimer);hideTimer=setTimeout(()=>{if($('#popup').hidden&&!document.activeElement.closest('#viewer button'))$('#viewer').classList.add('hide-controls')},2200)}
function toggleFullscreen(){if(document.fullscreenElement)document.exitFullscreen?.();else $('#viewer').requestFullscreen?.().catch(()=>notify('Fullscreen is unavailable in this preview.'))}
let settingsNavTarget=null,settingsNavTimer;
function setSettingsSection(link){if(!link)return;$$('.settings-nav a').forEach(a=>a.classList.toggle('active',a===link));const marker=$('.settings-nav-indicator');if(marker){marker.style.height=link.offsetHeight+'px';marker.style.transform=`translateY(${link.offsetTop-7}px)`}}
function settingsPage(){$('#page-heading').innerHTML='';const sections=['Appearance','Gallery','Viewer','Playback','Downloads','Keyboard shortcuts','Gelbooru connection'];$('#content').innerHTML=`<div class="settings-page"><nav class="settings-nav"><span class="settings-nav-indicator" aria-hidden="true"></span>${sections.map((x,i)=>`<a href="#section-${i}">${x}</a>`).join('')}</nav>${sections.map((x,i)=>`<section class="settings-section" id="section-${i}"><h2>${x}</h2>${x==='Appearance'?'<p class="provisional">Near-black gallery · blurred, dimmed current-image viewer background. Exact visual tokens are provisional.</p>':x==='Gallery'?`<div class="setting-row"><div>Thumbnail size<small>Shared across galleries</small></div><input type="range" id="settings-row" min="110" max="300" value="${state.row}" aria-label="Thumbnail size"></div>`:x==='Viewer'?`<div class="setting-row"><div>Enlarge from width<small>Width OR height threshold</small></div><input data-number="minW" type="number" value="${state.minW}" aria-label="Minimum width"></div><div class="setting-row"><div>Enlarge from height</div><input data-number="minH" type="number" value="${state.minH}" aria-label="Minimum height"></div><div class="setting-row"><div>Image preload count<small>Provisional default for the prototype</small></div><input data-number="preload" type="number" min="0" max="20" value="${state.preload}" aria-label="Preload count"></div>`:x==='Keyboard shortcuts'?Object.entries(state.bindings).map(([label,key])=>`<div class="setting-row"><span>${label}</span><span><button data-bind="${label}">${key||'Unassigned'}</button> <button data-clear="${label}" title="Clear binding">Clear</button></span></div>`).join(''):x==='Gelbooru connection'?'<p class="provisional">No credentials are collected in this local UI prototype. Production: enter → Validate → automatically save on success; stored keys are never revealed.</p>':`<p class="provisional">${x==='Playback'?'Autoplay and loop. Remember volume/mute; video positions are session-only.':'Server behavior is outside this prototype.'}</p>`}</section>`).join('')}<button id="reset-demo" class="search-submit">Reset sample data</button></div>`;$$('.settings-nav a').forEach(a=>a.onclick=e=>{e.preventDefault();setSettingsSection(a);settingsNavTarget=a.getAttribute('href');clearTimeout(settingsNavTimer);settingsNavTimer=setTimeout(()=>{settingsNavTarget=null},850);$(a.getAttribute('href')).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})});requestAnimationFrame(()=>setSettingsSection($('.settings-nav a')));$$('[data-number]').forEach(input=>input.onchange=()=>{state[input.dataset.number]=Math.max(0,+input.value);persist();notify('Saved')});$('#settings-row').oninput=e=>{state.row=+e.target.value;persist()};$$('[data-clear]').forEach(b=>b.onclick=()=>{state.bindings[b.dataset.clear]='';persist();settingsPage()});$$('[data-bind]').forEach(b=>b.onclick=()=>{const old=b.textContent;b.textContent='Press a key…';const capture=e=>{e.preventDefault();e.stopImmediatePropagation();document.removeEventListener('keydown',capture,true);if(e.key==='Escape'){b.textContent=old;return}const key=(e.ctrlKey||e.metaKey?'Ctrl/Cmd+':'')+(e.shiftKey?'Shift+':'')+e.key.toLowerCase();if(Object.entries(state.bindings).some(([label,value])=>label!==b.dataset.bind&&value===key)){b.textContent=old;notify('This shortcut is already assigned.');return}state.bindings[b.dataset.bind]=key;persist();settingsPage()};document.addEventListener('keydown',capture,true)});$('#reset-demo').onclick=()=>{localStorage.removeItem('panbooru-ui-v1');location.reload()}}
function render(){if(!isViewer())clearViewerHighlights();renderSidebar();renderToolbar();document.documentElement.style.setProperty('--row',state.row+'px');const v=current();if(v?.mode==='viewer'){viewerList=filtered(v).map(p=>p.id);$('#viewer').hidden=false;document.body.classList.add('viewing');renderMedia()}else{$('#viewer').hidden=true;document.body.classList.remove('viewing','left-open')}if(state.active==='settings')settingsPage();else if(state.active==='albums'||state.active==='saved')renderCards();else if(v)renderGallery();else{$('#page-heading').innerHTML='';$('#content').innerHTML='<div class="empty"><h2>A little room to explore.</h2><button id="empty-search">New search</button></div>';$('#empty-search').onclick=()=>newView()}requestAnimationFrame(()=>$('#scroll').scrollTop=v?.scroll||0)}
function simulateTask(a,ids){task={name:a.name,ids,index:0,paused:false,done:false};$('#taskbar').hidden=false;clearInterval(taskTimer);taskTimer=setInterval(()=>{if(!task||task.paused||task.done)return;if(task.index>=ids.length){task.done=true;$('#task-trigger span').style.background='#86ba96';setTimeout(()=>{if(task?.done){task=null;$('#taskbar').hidden=true}},2200);clearInterval(taskTimer);return}a.items=[...new Set([...a.items,ids[task.index++]])];if(a.cover.length<4)a.cover=a.items.slice(0,4);$('#task-trigger span').style.width=task.index/ids.length*100+'%';if(state.active==='albums')renderCards();persist()},180)}
$('#task-trigger').onclick=e=>openPopup(e.currentTarget,`<h3>Sample task · local simulation</h3><div class="muted">${escapeHTML(task?.name||'Completed')}<br>${task?.index||0} posts added</div><button class="menu-item" id="pause-task">${task?.paused?'Resume':'Pause'}</button><button class="menu-item" id="cancel-task">Cancel</button>`,()=>{$('#pause-task').onclick=()=>{if(task)task.paused=!task.paused;closePopup()};$('#cancel-task').onclick=()=>{clearInterval(taskTimer);task=null;$('#taskbar').hidden=true;closePopup()}});
// Handle middle-click before row handlers so nested controls cannot swallow or double-close it.
$('#sidebar').addEventListener('mousedown',e=>{if(e.button===1&&e.target.closest('[data-view],[data-album],[data-dest="favorites"]'))e.preventDefault()},true);
$('#sidebar').addEventListener('auxclick',e=>{if(e.button!==1)return;const row=e.target.closest('[data-view],[data-album],[data-dest="favorites"]');if(!row)return;e.preventDefault();e.stopImmediatePropagation();closeView(row.dataset.view||(row.dataset.album?'album:'+row.dataset.album:'favorites'))},true);
let galleryOptionsIdle;
$('#main').addEventListener('pointermove',()=>{const button=$('#gallery-options-float');if(!button)return;button.classList.add('revealed');clearTimeout(galleryOptionsIdle);galleryOptionsIdle=setTimeout(()=>button.classList.remove('revealed'),2200)});
$('#new-search').onclick=()=>{newView();$('#query')?.focus()};$('#back').onclick=leaveViewer;$('#previous').onclick=()=>step(-1);$('#next').onclick=()=>step(1);
$('#viewer').onmousemove=e=>{revealControls();if(e.clientX<6)document.body.classList.add('left-open')};$('#sidebar').onmouseleave=()=>{if(isViewer()&&!$('#sidebar').contains(document.activeElement))document.body.classList.remove('left-open')};$('#full-image').ondblclick=e=>{if(zoom>1.001){zoom=1;pan={x:0,y:0};transformImage()}else setZoom(base>=1?2:1/base,e.clientX,e.clientY)};
$('#full-image').onpointerdown=e=>{if(zoom<=1.001)return;viewerPointer={x:e.clientX,y:e.clientY,pan:{...pan}};e.target.setPointerCapture(e.pointerId);e.target.classList.add('dragging')};$('#full-image').onpointermove=e=>{if(!viewerPointer)return;pan.x=viewerPointer.pan.x+e.clientX-viewerPointer.x;pan.y=viewerPointer.pan.y+e.clientY-viewerPointer.y;transformImage()};$('#full-image').onpointerup=()=>{viewerPointer=null;$('#full-image').classList.remove('dragging')};
$('#media-area').addEventListener('wheel',e=>{e.preventDefault();if(e.ctrlKey||e.metaKey){setZoom(zoom*Math.exp(-e.deltaY*.008),e.clientX,e.clientY);return}if(zoom>1.001){pan.x-=e.deltaX;pan.y-=e.deltaY;transformImage();return}// Trackpad scrolling at the initial zoom does not navigate images.
},{passive:false});
let lastScroll=0;$('#scroll').onscroll=()=>{const el=$('#scroll'),v=current();$('#toolbar').classList.toggle('overlay-search',state.active!=='settings'&&el.scrollTop>24);if(state.active==='settings'){const top=el.getBoundingClientRect().top+45;const sections=$$('.settings-section');const active=sections.filter(section=>section.getBoundingClientRect().top<=top).at(-1)||sections[0];if(!settingsNavTarget)setSettingsSection($$('.settings-nav a').find(link=>link.getAttribute('href')==='#'+active?.id))}const focused=document.activeElement===$('#query');$('#toolbar').classList.toggle('scrolled-hidden',state.active!=='settings'&&!selecting&&!focused&&$('#popup').hidden&&el.scrollTop>lastScroll&&el.scrollTop>100);lastScroll=el.scrollTop;if(v&&!isViewer()){v.scroll=el.scrollTop;if(el.scrollHeight-el.scrollTop-el.clientHeight<700&&v.loaded<filtered(v).length){v.loaded+=18;renderGallery()}}};
function resizer(el,move){el.onpointerdown=e=>{e.preventDefault();el.setPointerCapture(e.pointerId);const x=e.clientX,y=e.clientY,initial={side:state.side,height:state.albumHeight,right:current()?.panelWidth||310};el.onpointermove=event=>move(event.clientX-x,event.clientY-y,initial);el.onpointerup=()=>{el.onpointermove=null;persist()}}}
resizer($('#side-resize'),(x,y,a)=>{state.side=Math.max(180,Math.min(420,a.side+x));document.documentElement.style.setProperty('--side',state.side+'px')});resizer($('#album-divider'),(x,y,a)=>{state.albumHeight=Math.max(70,Math.min(innerHeight*.6,a.height-y));$('#album-nav').style.height=state.albumHeight+'px'});resizer($('#right-resize'),(x,y,a)=>{const v=current(),actual=base*zoom;v.panelWidth=Math.max(230,Math.min(480,a.right-x));document.documentElement.style.setProperty('--right',v.panelWidth+'px');$('#viewer').style.setProperty('--view-right',v.panelWidth+'px');const manual=zoom>1.001;fitBase();if(manual)zoom=Math.max(1,actual/base);transformImage()});
document.addEventListener('click',e=>{if(isViewer()&&document.body.classList.contains('left-open')&&!e.composedPath().includes($('#sidebar'))){document.body.classList.remove('left-open');if($('#sidebar').contains(document.activeElement))document.activeElement.blur()}if(!e.target.closest('.popup')&&!e.target.closest('button')&&!e.target.closest('#query')&&!e.target.closest('#taskbar'))closePopup()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#dialog').open)return;if(!$('#popup').hidden||!$('#context-menu').hidden){e.preventDefault();closePopup(true);return}if(selecting){clearSelection();render();return}if(document.body.classList.contains('left-open')){document.body.classList.remove('left-open');return}if(isViewer()){if(document.fullscreenElement)return;leaveViewer();return}}
if(e.target.closest('input,textarea,select,[contenteditable=true]')||$('#dialog').open)return;
if((e.ctrlKey||e.metaKey)&&!e.shiftKey&&e.key.toLowerCase()==='z'){e.preventDefault();undoRemoval();return}
// Focus on an ordinary action button must not disable image navigation.
if(isViewer()&&!(e.ctrlKey||e.metaKey||e.altKey)&&['arrowleft','arrowright','a','d'].includes(e.key.toLowerCase())){e.preventDefault();step(['arrowleft','a'].includes(e.key.toLowerCase())?-1:1,true);return}
if(e.target.closest('button')&&['Enter',' '].includes(e.key))return;
const deselectKey=(e.ctrlKey||e.metaKey?'Ctrl/Cmd+':'')+(e.shiftKey?'Shift+':'')+e.key.toLowerCase();if(state.bindings['Delete selected images']===deselectKey){if(isViewer()&&['album','favorites'].includes(current()?.scope)){e.preventDefault();removeViewerImage();return}if(selecting){e.preventDefault();deleteSelectedImages();return}}
if(selecting&&state.bindings['Deselect all']===deselectKey){e.preventDefault();selection.clear();allQuery=false;anchor=null;render();return}
if((e.ctrlKey||e.metaKey)&&!e.shiftKey&&e.key.toLowerCase()==='a'&&(current()||state.active==='albums')){e.preventDefault();selecting=true;allQuery=true;selection=new Set(state.active==='albums'?state.albums.map(a=>a.id):activeIds());render();return}if(e.ctrlKey||e.metaKey||e.altKey)return;
const key=(e.shiftKey?'Shift+':'')+e.key.toLowerCase(),bind=label=>state.bindings[label]===key;if(bind('New search')){newView();$('#query')?.focus();return}if(bind('Reopen view'))return reopen();if(bind('Close view'))return closeView();if(!isViewer())return;if(['arrowleft','a'].includes(e.key.toLowerCase())){e.preventDefault();step(-1,true)}if(['arrowright','d'].includes(e.key.toLowerCase())){e.preventDefault();step(1,true)}if(bind('Fullscreen'))toggleFullscreen();if(bind('Tag sidebar'))togglePanel();if(bind('Left sidebar'))document.body.classList.toggle('left-open');if(bind('Favorite'))setFavorite(current().postId,!state.favorites.includes(current().postId));if(bind('Album picker'))albumPicker($('#viewer-bar button'),[current().postId])});
window.addEventListener('popstate',e=>{if(e.state?.id){checkpoint();state.active=e.state.id;restoreSelection();const v=current();if(v){if(e.state.q!==undefined){v.q=e.state.q;v.draft=v.q;v.filters=e.state.filters;v.draftFilters=structuredClone(v.filters)}v.mode=e.state.post?'viewer':'gallery';if(e.state.post)v.postId=e.state.post}render()}});window.addEventListener('resize',()=>{if(isViewer()){fitBase();transformImage()}});
let galleryWidth=0,galleryResizeFrame=0;new ResizeObserver(entries=>{const width=Math.round(entries[0].contentRect.width);if(width===galleryWidth)return;galleryWidth=width;cancelAnimationFrame(galleryResizeFrame);galleryResizeFrame=requestAnimationFrame(()=>{if(current()&&!isViewer())renderGallery()})}).observe($('#main'));window.addEventListener('beforeunload',checkpoint);
